// API contract between the DealScope FastAPI server (src/dealscope/api) and this frontend.
// All user-facing wording is produced server-side in plain language; the UI must not show raw
// internal codes (reason codes, stage enums) except inside an optional "technical details" disclosure.

export type RunMode = "live" | "synthetic";
export type Tone = "good" | "neutral" | "caution" | "bad" | "info";

export interface ProviderStatus {
  key: "crustdata" | "llm" | "neatlogs" | "jobs_pricing";
  label: string; // e.g. "Company data (Crustdata)"
  connected: boolean;
  detail: string; // e.g. "Connected" / "Model: gemini-3.1-flash-lite" / "Not configured"
}

export interface BudgetSummary {
  spendable: number; // credits allowed for product use (total minus reserve)
  estimated_used: number;
  actual_used: number; // confirmed from provider response headers
  reserved: number;
  remaining: number;
  unknown_calls: number;
  reserve: number; // credits held back and never spent
  total: number;
}

export interface StatusResponse {
  providers: ProviderStatus[];
  live_budget: BudgetSummary;
  max_case_credits: number;
  live_available: boolean; // false when no Crustdata key: live runs are refused, never faked
}

export interface Scenario {
  id: string; // "scenario_a" | "scenario_b" | "synthetic_case"
  label: string;
  description: string;
  target_domain: string;
  competitor_domains: string[];
  deal_thesis: string;
}

export interface FaultOption {
  id: string; // "none" | "retry_success" | "retry_exhausted" | "auth_failure"
  label: string;
  description: string;
}

export interface IdentityCandidate {
  name: string | null;
  primary_domain: string | null;
  employee_count_range: string | null;
}

export interface IdentityResult {
  domain: string;
  ok: boolean;
  status: "ok" | "ambiguous" | "mismatch" | "no_match" | "error";
  resolved_name: string | null;
  match_count: number;
  message: string; // plain-language explanation, e.g. "23 different companies use this domain..."
  candidates: IdentityCandidate[];
}

export interface CreateCaseRequest {
  target_domain: string;
  competitor_domains: string[];
  deal_thesis: string;
  lookback_months: number;
  max_case_credits: number;
  mode: RunMode;
  scenario_id?: string; // synthetic only
  fault_id?: string; // synthetic only
}

export interface CreateCaseResponse {
  case_id: string;
}

export interface CaseListItem {
  case_id: string;
  target: string;
  mode: RunMode;
  status_label: string; // "Complete", "Partial - can resume", "Running", "Failed"
  tone: Tone;
  risk_label: string; // "Watch (32/100)" or "Not enough evidence"
  updated_at: string; // ISO
}

export interface Assessment {
  risk_score: number | null; // 0-100, null when coverage < 60%
  risk_band: string | null; // "Low signal" | "Watch" | "Elevated" | "High signal"
  risk_tone: Tone;
  headline: string; // one plain sentence summarising the result
  coverage_pct: number;
  coverage_label: string; // "Enough evidence to score" / "Provisional" / "Not enough evidence"
  confidence: number; // 0-100, evidence quality (separate from risk)
  confidence_label: string; // "High" | "Medium" | "Low"
  explainer: string; // how to read risk vs coverage vs confidence
}

export interface SignalView {
  id: string; // "S1".."S5"
  name: string; // plain name, e.g. "Engineering team vs. company growth"
  question: string; // the question this signal answers
  weight_pct: number;
  scored: boolean;
  score: number | null;
  band: string | null; // band label for this signal score
  tone: Tone;
  status_label: string; // "Scored" | "Partly scored (thin data)" | "Not scored"
  confidence: number;
  finding: string; // plain-language result, built from reason codes and raw measures
  why_it_matters: string;
  limitations: string[];
  evidence_ids: string[];
  technical: { reason_codes: string[]; state: string };
}

export interface EvidenceRef {
  id: string;
  label: string; // "Company profile - notion.com" / "Job posting - Staff SRE"
  date: string | null;
  source: string; // "Crustdata /job/search" or "Synthetic fixture"
}

export interface FindingView {
  id: string;
  kind: "Fact" | "Interpretation" | "Hypothesis" | "Question";
  severity: "low" | "medium" | "high";
  text: string;
  verification: "Verified" | "Verified with caveats";
  caveats: string[];
  evidence: EvidenceRef[];
  counter_evidence: EvidenceRef[];
  alternatives: string[];
  limitations: string[];
}

export interface StepView {
  n: number;
  at: string; // ISO timestamp
  kind: "plan" | "tool" | "retry" | "score" | "stage" | "resume" | "blocked" | "note";
  title: string; // plain, e.g. "Checked open engineering roles at notion.com"
  detail: string; // plain explanation, e.g. "Found 25 postings; 14 were reposted."
  actor: string; // "AI planner" | "Rule-based planner" | "Baseline" | "System" | "Retry policy"
  tone: Tone;
  credits: string | null; // e.g. "2 credits (confirmed)" / "from cache, 0 credits"
}

export interface CompanyRow {
  domain: string;
  role: "Target" | "Peer";
  name: string | null;
  headcount: number | null;
  total_growth: Record<string, number>; // period label ("3m","6m","12m") -> percent
  engineering_headcount: number | null;
  engineering_growth: Record<string, number>;
  open_jobs: number | null;
  data_quality_flags: string[]; // plain sentences
  evidence_id: string;
}

export interface PersonRow {
  ref: string; // opaque, never a name
  role_group: string; // plain: "Technical leadership"
  title_at_target: string | null;
  left_target: string | null; // "2026-05" or null if still there / unknown
  status: string; // "Left in lookback window" | "Left earlier" | "Still at target" | "End date unknown"
  now_at: string | null;
  now_at_competitor: boolean;
  evidence_id: string;
}

export interface JobRow {
  title: string;
  capability: string; // plain: "Security"
  posted: string | null;
  reposted: boolean | null;
  openings: number | null;
  url: string | null;
  evidence_id: string;
}

export interface CreditsView {
  cap: number;
  estimated_used: number;
  actual_used: number;
  reserved: number;
  remaining: number;
  unknown_calls: number;
  simulated: boolean; // synthetic runs: simulated accounting, no real credits
}

export interface VerificationView {
  published: number;
  verified: number;
  with_caveats: number;
  rejected: number;
  grounded_rate: number | null; // 0-1
  rejected_reasons: { reason: string; count: number }[]; // plain reasons
  ai_draft_used: boolean; // false when the AI write-up was unavailable and only rule-based findings are shown
}

export interface CaseView {
  case_id: string;
  mode: RunMode;
  synthetic: boolean;
  target: string;
  peers: string[];
  thesis: string;
  lookback_months: number;
  running: boolean;
  status_label: string;
  status_tone: Tone;
  status_detail: string; // plain explanation of how/why the run ended
  can_resume: boolean;
  current_question: string | null;
  planner_turns: number;
  tool_calls: number;
  assessment: Assessment | null; // null until the first scoring
  signals: SignalView[];
  findings: FindingView[];
  questions: string[]; // diligence questions for management
  steps: StepView[];
  companies: CompanyRow[];
  people: PersonRow[];
  jobs: JobRow[];
  credits: CreditsView;
  verification: VerificationView | null;
  trace_ids: string[];
  llm_model: string | null;
  updated_at: string;
  report_available: boolean;
}

// Shape of the "How it works" walkthrough content (frontend/src/content/howItWorks.ts).
// Evidence images are repository paths under evidence/ (e.g. "evidence/neatlogs/screenshots/x.png");
// the frontend loads them from the API at /api/evidence/<path relative to evidence/>.

export interface ContentTable {
  headers: string[];
  rows: string[][];
}

export interface EvidenceImage {
  path: string; // repo-relative, must start with "evidence/"
  caption: string;
}

export interface HowItWorksSection {
  id: string; // anchor id, kebab-case
  title: string;
  summary: string; // one or two sentences shown in the section header
  paragraphs: string[];
  bullets?: string[];
  table?: ContentTable;
  images?: EvidenceImage[];
}

export interface HowItWorksContent {
  intro: string;
  sections: HowItWorksSection[];
}

"""FastAPI server for the DealScope web UI (contract: frontend/src/api/types.ts).

Run:  .venv/Scripts/uvicorn dealscope.api.server:app --port 8000   (serves frontend/dist at / when built)
Investigations run in background threads; the UI polls GET /api/cases/{id}. State lives in SQLite, so a server
restart loses nothing and a partial case can be resumed.
"""

from __future__ import annotations

import json
import logging
import threading
from decimal import Decimal
from pathlib import Path
from typing import Literal

from fastapi import FastAPI, HTTPException
from fastapi.middleware.cors import CORSMiddleware
from fastapi.responses import FileResponse, JSONResponse, PlainTextResponse
from fastapi.staticfiles import StaticFiles
from pydantic import BaseModel, Field, ValidationError

from dealscope.agent.orchestrator import ConfigError, build_orchestrator
from dealscope.api import views
from dealscope.budget.governor import CreditGovernor
from dealscope.config import Settings, get_settings
from dealscope.domain.enums import RunMode
from dealscope.domain.models import CaseInput, normalize_domain
from dealscope.observability import tracing
from dealscope.persistence.repository import Repository

log = logging.getLogger(__name__)
ROOT = Path(__file__).resolve().parents[3]
FIXTURES = ROOT / "fixtures"
EVIDENCE = ROOT / "evidence"
DIST = ROOT / "frontend" / "dist"

SCENARIOS = {
    "scenario_a": ("Scenario A - engineering lags the company",
                   "Engineering headcount shrinks while the company grows, several critical roles are open and senior "
                   "leaders have left. Shows the agent prioritising hiring and continuity checks."),
    "scenario_b": ("Scenario B - steady growth, thin history",
                   "Engineering keeps pace with the company but most profile histories lack dates. Shows the agent "
                   "choosing a different path: broadening people coverage instead of hiring checks."),
    "synthetic_case": ("Original spec fixture",
                       "The minimal example from the specification: one departure, one reposted role."),
}
FAULTS = {
    "none": ("No failure", "Normal run.", None),
    "retry_success": ("Temporary outage, then recovery",
                      "The first company lookup fails twice (HTTP 503) and succeeds on the third attempt.",
                      {"enrich_company": [503, 503]}),
    "retry_exhausted": ("Outage that outlasts retries",
                        "The first company lookup fails three times. The case ends as partial; press Resume to "
                        "recover without repeating completed requests.", {"enrich_company": [503, 503, 503]}),
    "auth_failure": ("Rejected credentials",
                     "The provider rejects the key (HTTP 401). The agent stops cleanly and never substitutes demo data.",
                     {"enrich_company": [401]}),
}

app = FastAPI(title="DealScope API", version="0.2.0")
app.add_middleware(CORSMiddleware, allow_origins=["http://localhost:5173", "http://127.0.0.1:5173"],
                   allow_methods=["*"], allow_headers=["*"])

_runs: dict[str, threading.Thread] = {}
_runs_lock = threading.Lock()


def _settings() -> Settings:
    return get_settings()


def _repo() -> Repository:
    return Repository(_settings().dealscope_db_path)


@app.on_event("startup")
def _startup() -> None:
    s = _settings()
    tracing.init_tracing(s.neatlogs_api_key.get_secret_value() if s.neatlogs_api_key else None,
                         workflow_name="dealscope")


@app.on_event("shutdown")
def _shutdown() -> None:
    tracing.shutdown()


def _running(case_id: str) -> bool:
    with _runs_lock:
        t = _runs.get(case_id)
        return bool(t and t.is_alive())


def _start_thread(case_id: str, mode: RunMode, scenario: Path | None, faults: dict | None, resume: bool) -> None:
    def work() -> None:
        repo = _repo()
        try:
            orch = build_orchestrator(_settings(), mode, repo=repo, fixture_path=scenario, faults=faults)
            orch.run(case_id, resume=resume)
        except Exception:  # state is persisted as failed by the orchestrator; log for the operator
            log.exception("run failed for %s", case_id)
        finally:
            repo.close()

    t = threading.Thread(target=work, name=f"run-{case_id}", daemon=True)
    with _runs_lock:
        _runs[case_id] = t
    t.start()


# ---------------------------------------------------------------------------
# Schemas
# ---------------------------------------------------------------------------


class CreateCase(BaseModel):
    target_domain: str
    competitor_domains: list[str]
    deal_thesis: str
    lookback_months: int = 12
    max_case_credits: float = 40
    mode: Literal["live", "synthetic"] = "synthetic"
    scenario_id: str | None = None
    fault_id: str | None = None


class IdentityRequest(BaseModel):
    domains: list[str] = Field(min_length=1, max_length=6)


# ---------------------------------------------------------------------------
# Endpoints
# ---------------------------------------------------------------------------


@app.get("/api/status")
def status() -> dict:
    s = _settings()
    repo = _repo()
    try:
        g = CreditGovernor(repo, s, pool="live").global_summary()
    finally:
        repo.close()
    st = s.public_status()
    providers = [
        {"key": "crustdata", "label": "Company data (Crustdata)", "connected": bool(st["crustdata_key_present"]),
         "detail": "Connected" if st["crustdata_key_present"] else "No API key - live runs disabled"},
        {"key": "llm", "label": "AI planner and writer (Gemini)", "connected": bool(st["llm_key_present"]),
         "detail": f"Model: {s.llm_model}" if st["llm_key_present"] else "No API key - rule-based planner only"},
        {"key": "neatlogs", "label": "Run tracing (neatlogs)", "connected": tracing.tracing_enabled(),
         "detail": "Traces are being recorded" if tracing.tracing_enabled() else "Not connected"},
        {"key": "jobs_pricing", "label": "Job postings pricing", "connected": bool(st["jobs_price_configured"]),
         "detail": "Price confirmed from account" if st["jobs_price_configured"]
         else "Price not confirmed - job searches blocked in live mode"},
    ]
    budget = {k: float(g[k]) for k in ("spendable", "estimated_used", "actual_used", "reserved", "remaining")}
    budget.update(unknown_calls=int(g["unknown_count"]), reserve=float(s.crustdata_global_reserve_credits),
                  total=float(s.crustdata_total_credits))
    return {"providers": providers, "live_budget": budget, "max_case_credits": float(s.crustdata_max_case_credits),
            "live_available": bool(st["crustdata_key_present"])}


@app.get("/api/scenarios")
def scenarios() -> list[dict]:
    out = []
    for sid, (label, desc) in SCENARIOS.items():
        path = FIXTURES / f"{sid}.json"
        if not path.exists():
            continue
        c = json.loads(path.read_text(encoding="utf-8")).get("case", {})
        out.append({"id": sid, "label": label, "description": desc, "target_domain": c.get("target_domain", ""),
                    "competitor_domains": c.get("competitor_domains", []), "deal_thesis": c.get("deal_thesis", "")})
    return out


@app.get("/api/faults")
def faults() -> list[dict]:
    return [{"id": k, "label": v[0], "description": v[1]} for k, v in FAULTS.items()]


@app.post("/api/identity-check")
def identity_check(req: IdentityRequest) -> list[dict]:
    s = _settings()
    if s.crustdata_api_key is None:
        raise HTTPException(400, "Live data is not configured (no Crustdata API key).")
    from dealscope.providers.crustdata import CrustdataClient

    client = CrustdataClient(s.crustdata_api_key.get_secret_value(), api_version=s.crustdata_api_version,
                             base_url=s.crustdata_base_url, timeout_s=s.dealscope_http_timeout_seconds,
                             max_retries=s.dealscope_max_retries)
    out = []
    for raw in req.domains:
        try:
            out.append(views.identity_view(client.identify_company(normalize_domain(raw))))
        except ValueError as exc:
            out.append({"domain": raw, "ok": False, "status": "error", "resolved_name": None, "match_count": 0,
                        "message": f"Not a valid company domain: {exc}", "candidates": []})
        except Exception as exc:  # provider/network error: surface it, nothing metered was attempted
            out.append({"domain": raw, "ok": False, "status": "error", "resolved_name": None, "match_count": 0,
                        "message": f"Could not check this domain right now ({type(exc).__name__}).", "candidates": []})
    return out


@app.post("/api/cases")
def create_case(req: CreateCase) -> dict:
    s = _settings()
    mode = RunMode(req.mode)
    try:
        case_input = CaseInput(target_domain=req.target_domain, competitor_domains=req.competitor_domains,
                               deal_thesis=req.deal_thesis, lookback_months=req.lookback_months,
                               max_case_credits=Decimal(str(req.max_case_credits)), mode=mode)
    except ValidationError as exc:
        msg = "; ".join(e["msg"].removeprefix("Value error, ") for e in exc.errors())
        raise HTTPException(422, msg) from exc
    scenario = faults_cfg = None
    if mode == RunMode.SYNTHETIC:
        sid = req.scenario_id or "scenario_a"
        if sid not in SCENARIOS:
            raise HTTPException(422, f"Unknown scenario {sid}")
        scenario = FIXTURES / f"{sid}.json"
        faults_cfg = FAULTS.get(req.fault_id or "none", FAULTS["none"])[2]
    repo = _repo()
    try:
        orch = build_orchestrator(s, mode, repo=repo, fixture_path=scenario, faults=faults_cfg, llm=None)
        state = orch.create_case(case_input)
    except ConfigError as exc:
        raise HTTPException(400, str(exc)) from exc
    finally:
        repo.close()
    _start_thread(state.case_id, mode, scenario, faults_cfg, resume=False)
    return {"case_id": state.case_id}


@app.post("/api/cases/{case_id}/resume")
def resume_case(case_id: str) -> dict:
    repo = _repo()
    try:
        state = repo.load_case(case_id)
    finally:
        repo.close()
    if state is None:
        raise HTTPException(404, "Case not found")
    if _running(case_id):
        raise HTTPException(409, "This case is already running")
    scenario = None
    if state.mode == RunMode.SYNTHETIC:
        # Synthetic cases re-use the fixture recorded for the target (scenario A/B share domains; A is the default).
        scenario = FIXTURES / "scenario_a.json"
    _start_thread(case_id, state.mode, scenario, None, resume=True)
    return {"case_id": case_id}


@app.get("/api/cases")
def list_cases() -> list[dict]:
    repo = _repo()
    try:
        out = []
        for row in repo.list_cases()[:100]:
            st = repo.load_case(row["case_id"])
            if st is not None:
                out.append(views.case_list_item(st, _running(st.case_id)))
        return out
    finally:
        repo.close()


@app.get("/api/cases/{case_id}")
def get_case(case_id: str) -> dict:
    s = _settings()
    repo = _repo()
    try:
        state = repo.load_case(case_id)
        if state is None:
            raise HTTPException(404, "Case not found")
        pool = "synthetic" if state.mode == RunMode.SYNTHETIC else "live"
        summary = CreditGovernor(repo, s, pool=pool).case_summary(case_id, state.credit_budget)
        return views.case_view(state, repo.get_evidence(case_id), repo.list_events(case_id),
                               repo.latest_report(case_id), summary, _running(case_id))
    finally:
        repo.close()


@app.get("/api/cases/{case_id}/report.md", response_class=PlainTextResponse)
def report_md(case_id: str) -> PlainTextResponse:
    repo = _repo()
    try:
        rep = repo.latest_report(case_id)
    finally:
        repo.close()
    if rep is None:
        raise HTTPException(404, "No report yet")
    return PlainTextResponse(rep["markdown"], media_type="text/markdown",
                             headers={"Content-Disposition": f'attachment; filename="dealscope-{case_id}.md"'})


@app.get("/api/cases/{case_id}/bundle.json")
def report_bundle(case_id: str) -> JSONResponse:
    repo = _repo()
    try:
        rep = repo.latest_report(case_id)
    finally:
        repo.close()
    if rep is None:
        raise HTTPException(404, "No report yet")
    return JSONResponse(json.loads(json.dumps(rep["bundle"], default=str)),
                        headers={"Content-Disposition": f'attachment; filename="dealscope-{case_id}.json"'})


_EVIDENCE_TYPES = {".png", ".jpg", ".jpeg", ".webp", ".pdf"}


@app.get("/api/evidence/{path:path}")
def evidence_file(path: str) -> FileResponse:
    target = (EVIDENCE / path).resolve()
    if EVIDENCE.resolve() not in target.parents or target.suffix.lower() not in _EVIDENCE_TYPES or not target.is_file():
        raise HTTPException(404, "Not found")
    return FileResponse(target)


# Serve the built single-page app (frontend/dist) with client-side routing fallback.
if DIST.exists():
    app.mount("/assets", StaticFiles(directory=DIST / "assets"), name="assets")

    @app.get("/{full_path:path}", include_in_schema=False)
    def spa(full_path: str) -> FileResponse:
        candidate = (DIST / full_path).resolve()
        if full_path and DIST.resolve() in candidate.parents and candidate.is_file():
            return FileResponse(candidate)
        return FileResponse(DIST / "index.html")

